B.b17=new A.a("\u064a\u0639\u062a\u0628\u0631 \u0627\u0644\u062d\u062c \u0623\u062d\u062f \u0627\u0644\u0623\u0631\u0643\u0627\u0646 \u0627\u0644\u062e\u0645\u0633\u0629 \u0648\u0642\u062f \u0641\u0631\u0636 \u0641\u064a \u0627\u0644\u0639\u0627\u0645 \u0627\u0644\u0639\u0627\u0634\u0631 \u0648\u0647\u0630\u0627 \u0645\u0627\u0630\u0647\u0628 \u0625\u0644\u064a\u0647 \u0627\u0628\u0646 \u0627\u0644\u0642\u064a\u0645 \u0648\u0627\u0633\u062a\u062f\u0644 \u0628\u0623\u062f\u0644\u0629 \u0642\u0648\u064a\u0629 \u0648\u0647\u0648 \u0627\u0644\u0644\u0627\u0626\u0642 \u0628\u0647\u062f\u064a\u0647 \ufdfa \u0641\u064a \u0639\u062f\u0645 \u062a\u0623\u062e\u064a\u0631 \u0645\u0627\u0647\u0648 \u0641\u0631\u0636 \u0644\u0623\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u064a\u0642\u0648\u0644: \u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u062d\u0650\u062c\u0651\u064f \u0627\u0644\u0652\u0628\u064e\u064a\u0652\u062a\u0650 \u0645\u064e\u0646\u0650 \u0627\u0633\u0652\u062a\u064e\u0637\u064e\u0627\u0639\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0633\u064e\u0628\u0650\u064a\u0644\u0627 - \u0633\u0648\u0631\u0629 \u0622\u0644 \u0639\u0645\u0631\u0627\u0646 \u060c \u0648\u0642\u062f \u0646\u0632\u0644\u062a \u0639\u0627\u0645 \u0627\u0644\u0648\u0641\u0648\u062f \u0623\u0648\u0627\u062e\u0631 \u0633\u0646\u0629 \u062a\u0633\u0639.",null)
B.b8O=new A.a("\u0644\u0645 \u064a\u062d\u062c \u0627\u0644\u0646\u0628\u064a \ufdfa \u0645\u0646 \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u063a\u064a\u0631 \u062d\u062c\u062a\u0647 \u0627\u0644\u062a\u064a \u0643\u0627\u0646\u062a \u0641\u064a \u0627\u0644\u0639\u0627\u0645 \u0627\u0644\u0639\u0627\u0634\u0631 \u0648\u0639\u0631\u0641\u062a \u0647\u0630\u0647 \u0627\u0644\u062d\u062c\u0629 \u0628\u062d\u062c\u0629 \u0627\u0644\u0628\u0644\u0627\u063a \u0648\u062d\u062c\u0629 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0648\u062d\u062c\u0629 \u0627\u0644\u0648\u062f\u0627\u0639 \u0644\u0623\u0646\u0647 \ufdfa \u0648\u062f\u0639 \u0627\u0644\u0646\u0627\u0633 \u0641\u064a\u0647\u0627 \u0648\u0644\u0645 \u064a\u062d\u062c \u0628\u0639\u062f\u0647\u0627.",null)
B.aKv=new A.a("\u0648\u0644\u0645\u0627 \u0646\u0632\u0644\u062a \u0627\u0644\u0622\u064a\u0629: \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u0623\u064e\u0643\u0652\u0645\u064e\u0644\u0652\u062a\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u062f\u0650\u064a\u0646\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u062a\u0652\u0645\u064e\u0645\u0652\u062a\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0646\u0650\u0639\u0652\u0645\u064e\u062a\u0650\u064a \u0648\u064e\u0631\u064e\u0636\u0650\u064a\u062a\u064f \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0625\u0650\u0633\u0652\u0644\u0627\u0645\u064e \u062f\u0650\u064a\u0646\u064b\u0627 - \u0633\u0648\u0631\u0629 \u0627\u0644\u0645\u0627\u0626\u062f\u0629 \u060c \u0628\u0643\u0649 \u0628\u0639\u0636 \u0627\u0644\u0635\u062d\u0627\u0628\u0629 \u0648\u0645\u0646\u0647\u0645 \u0639\u0645\u0631 \u0628\u0646 \u0627\u0644\u062e\u0637\u0627\u0628 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u060c \u0648\u0643\u0623\u0646\u0647\u0645 \u0641\u0647\u0645\u0648\u0627 \u0645\u0646\u0647\u0627 \u0627\u0644\u0625\u0634\u0627\u0631\u0629 \u0625\u0644\u0649 \u0642\u0631\u0628 \u0623\u062c\u0644 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0648\u0644\u0645\u0627 \u0642\u064a\u0644 \u0644\u0633\u064a\u062f\u0646\u0627 \u0639\u0645\u0631: \u0645\u0627\u064a\u0628\u0643\u064a\u0643\u061f \u0642\u0627\u0644: \u0625\u0646\u0647 \u0644\u064a\u0633 \u0628\u0639\u062f \u0627\u0644\u0643\u0645\u0627\u0644 \u0625\u0644\u0627 \u0627\u0644\u0646\u0642\u0635\u0627\u0646 \u0648\u0643\u0627\u0646 \u0639\u062f\u062f \u0627\u0644\u0630\u064a \u0645\u0639 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0623\u0643\u062b\u0631 \u0645\u0646 \u0645\u0627\u0626\u0629 \u0623\u0644\u0641.",null)
