B.aPn=new A.a("\u0648\u0641\u062f \u0636\u0645\u0627\u062f \u0627\u0644\u0623\u0632\u062f\u064a \u0625\u0644\u0649 \u0645\u0643\u0629\u060c \u0648\u062a\u0623\u062b\u0631 \u0628\u062f\u0639\u0627\u0648\u0649 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0639\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u060c \u062d\u062a\u0649 \u0627\u0633\u062a\u0642\u0631 \u0641\u064a \u0646\u0641\u0633\u0647 \u0623\u0646\u0647 \u0645\u0635\u0627\u0628 \u0628\u0627\u0644\u062c\u0646\u0648\u0646\u060c \u0643\u0645\u0627 \u064a\u062a\u0647\u0645\u0647 \u0628\u0630\u0644\u0643 \u0632\u0639\u0645\u0627\u0621 \u0645\u0643\u0629\u060c \u0648\u0643\u0627\u0646 \u0636\u0645\u0627\u062f \u0645\u0646 \u0623\u0632\u062f \u0634\u0646\u0648\u0621\u0629\u060c \u0648\u0643\u0627\u0646 \u064a\u0639\u0627\u0644\u062c \u0645\u0646 \u0627\u0644\u062c\u0646\u0648\u0646\u060c \u0641\u0644\u0645\u0627 \u0633\u0645\u0639 \u0633\u0641\u0647\u0627\u0621 \u0645\u0643\u0629 \u064a\u0642\u0648\u0644\u0648\u0646 \u0625\u0646 \u0645\u062d\u0645\u062f\u064b\u0627 \ufdfa \u0645\u062c\u0646\u0648\u0646 \u0641\u0642\u0627\u0644: \u0644\u0648 \u0623\u0646\u064a \u0631\u0623\u064a\u062a \u0647\u0630\u0627 \u0627\u0644\u0631\u062c\u0644 \u0644\u0639\u0644 \u0627\u0644\u0644\u0647 \u064a\u0634\u0641\u064a\u0647 \u0639\u0644\u0649 \u064a\u062f\u064a.",null)
B.aV8=new A.a("\u0642\u0627\u0644: \u0641\u0644\u0642\u064a\u0647\u060c \u0641\u0642\u0627\u0644: \u064a\u0627 \u0645\u062d\u0645\u062f \u0625\u0646\u064a \u0623\u0631\u0642\u064a \u0645\u0646 \u0647\u0630\u0647 \u0627\u0644\u0631\u064a\u062d \u060c \u0648\u0625\u0646 \u0627\u0644\u0644\u0647 \u064a\u0634\u0641\u064a \u0639\u0644\u0649 \u064a\u062f\u064a \u0645\u0646 \u0634\u0627\u0621. \u0641\u0647\u0644 \u0644\u0643\u061f \u0641\u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa : \u0625\u0646 \u0627\u0644\u062d\u0645\u062f \u0644\u0644\u0647\u060c \u0646\u062d\u0645\u062f\u0647 \u0648\u0646\u0633\u062a\u0639\u064a\u0646\u0647\u060c \u0648\u0645\u0646 \u064a\u0647\u062f\u0647 \u0627\u0644\u0644\u0647 \u0641\u0644\u0627 \u0645\u0636\u0644 \u0644\u0647 \u0648\u0645\u0646 \u064a\u0636\u0644\u0644 \u0641\u0644\u0627 \u0647\u0627\u062f\u064a \u0644\u0647\u060c \u0648\u0623\u0634\u0647\u062f \u0623\u0646 \u0644\u0627 \u0625\u0644\u0647 \u0625\u0644\u0627 \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647 \u0644\u0627 \u0634\u0631\u064a\u0643 \u0644\u0647\u060c \u0648\u0623\u0646 \u0645\u062d\u0645\u062f\u064b\u0627 \u0639\u0628\u062f\u0647 \u0648\u0631\u0633\u0648\u0644\u0647\u060c \u0623\u0645\u0627 \u0628\u0639\u062f.",null)
