B.b0g=new A.a("\u0644\u0645\u0627 \u0627\u0633\u062a\u0634\u0647\u062f \u0623\u062e\u0648\u0647\u0627 \u062d\u0645\u0632\u0629 \u0628\u0646 \u0639\u0628\u062f\u0627\u0644\u0645\u0637\u0644\u0628 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0641\u064a \u0623\u062d\u062f\u060c \u0648\u062c\u0627\u0621\u062a \u0644\u062a\u0646\u0638\u0631 \u0625\u0644\u064a\u0647 \u0648\u0642\u062f \u0645\u062b\u0644 \u0628\u0647 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u0641\u062c\u062f\u0639\u0648\u0627 \u0623\u0646\u0641\u0647 \u0648\u0628\u0642\u0631\u0648\u0627 \u0628\u0637\u0646\u0647 \u0648\u0642\u0637\u0639\u0648\u0627 \u0623\u0630\u0646\u064a\u0647 \u0648\u0645\u0630\u0627\u0643\u064a\u0631\u0647 \u0641\u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0644\u0627\u0628\u0646\u0647\u0627 \u0627\u0644\u0632\u0628\u064a\u0631 \u0628\u0646 \u0627\u0644\u0639\u0648\u0627\u0645:\u0627\u0644\u0642\u0647\u0627 \u0641\u0623\u0631\u062c\u0639\u0647\u0627 \u0644\u0627\u062a\u0631\u0649 \u0645\u0627 \u0628\u0623\u062e\u064a\u0647\u0627 \u0641\u0642\u0627\u0644 \u0644\u0647\u0627: \u064a\u0627 \u0623\u0645\u0647 \u0625\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u064a\u0623\u0645\u0631\u0643 \u0623\u0646 \u062a\u0631\u062c\u0639\u064a \u0642\u0627\u0644\u062a: \u0648\u0644\u0645\u061f \u0648\u0642\u062f \u0628\u0644\u063a\u0646\u064a \u0623\u0646\u0647 \u0642\u062f \u0645\u062b\u0644 \u0628\u0623\u062e\u064a \u0648\u0630\u0644\u0643 \u0641\u064a \u0627\u0644\u0644\u0647 \u0641\u0645\u0627 \u0623\u0631\u0636\u0627\u0646\u0627 \u0628\u0645\u0627 \u0643\u0627\u0646 \u0645\u0646 \u0630\u0644\u0643! \u0644\u0623\u062d\u062a\u0633\u0628\u0646 \u0648\u0644\u0623\u0635\u0628\u0631\u0646 \u0625\u0646 \u0634\u0627\u0621 \u0627\u0644\u0644\u0647.",null)
B.aSy=new A.a("\u0641\u0648\u0642\u0641\u062a \u0648\u0623\u062e\u0631\u062c\u062a \u062b\u0648\u0628\u064a\u0646 \u0645\u0639\u0647\u0627 \u0641\u0642\u0627\u0644\u062a: \u0647\u0630\u0627\u0646 \u062b\u0648\u0628\u0627\u0646 \u062c\u0626\u062a \u0628\u0647\u0645\u0627 \u0644\u0623\u062e\u064a \u062d\u0645\u0632\u0629 \u0641\u0643\u0641\u0646\u0648\u0647 \u0641\u064a\u0647\u0645\u0627\u060c  \u0641\u062c\u0626\u0646\u0627 \u0628\u0627\u0644\u062b\u0648\u0628\u064a\u0646 \u0644\u0646\u0643\u0641\u0646 \u0641\u064a\u0647\u0645\u0627 \u062d\u0645\u0632\u0629 \u0641\u0625\u0630\u0627 \u0625\u0644\u0649 \u062c\u0646\u0628\u0647 \u0631\u062c\u0644 \u0645\u0646 \u0627\u0644\u0623\u0646\u0635\u0627\u0631 \u0642\u062a\u064a\u0644 \u0641\u0639\u0644 \u0628\u0647 \u0643\u0645\u0627 \u0641\u0639\u0644 \u0628\u062d\u0645\u0632\u0629 \u0642\u0627\u0644: \u0641\u0648\u062c\u062f\u0646\u0627 \u063a\u0636\u0627\u0636\u0629 \u0648\u062e\u0646\u0649 \u0623\u0646 \u064a\u0643\u0641\u0646 \u062d\u0645\u0632\u0629 \u0641\u064a \u062b\u0648\u0628\u064a\u0646 \u0648\u0627\u0644\u0623\u0646\u0635\u0627\u0631\u064a \u0644\u0627\u0643\u0641\u0646 \u0644\u0647 \u0641\u0642\u0644\u0646\u0627 \u0644\u062d\u0645\u0632\u0629 \u062b\u0648\u0628 \u0648\u0644\u0644\u0623\u0646\u0635\u0627\u0631\u064a \u062b\u0648\u0628 \u0641\u0642\u062f\u0631\u0646\u0627\u0647\u0645\u0627 \u0641\u0643\u0627\u0646 \u0623\u062d\u062f\u0647\u0645\u0627 \u0623\u0643\u0628\u0631 \u0645\u0646 \u0627\u0644\u0622\u062e\u0631 \u0641\u0623\u0642\u0631\u0639\u0646\u0627 \u0628\u064a\u0646\u0647\u0645\u0627 \u0641\u0643\u0641\u0646\u0627 \u0643\u0644 \u0648\u0627\u062d\u062f \u0645\u0646\u0647\u0645\u0627 \u0641\u064a \u0627\u0644\u062b\u0648\u0628 \u0627\u0644\u0630\u064a \u0635\u0627\u0631 \u0644\u0647.",null)
