B.aG5=new A.a("\u0631\u0623\u0649 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0623\u0646 \u064a\u063a\u062a\u0646\u0645 \u0641\u0631\u0635\u0629 \u0648\u062c\u0648\u062f\u0647 \u0628\u062c\u064a\u0634\u0647 \u0642\u0631\u064a\u0628\u0627\u064b \u0645\u0646 \u0645\u0643\u0629 \u0641\u0642\u0631\u0631 \u0623\u0646 \u064a\u0642\u0648\u0645 \u0628\u0645\u0646\u0627\u0648\u0631\u0629 \u0639\u0633\u0643\u0631\u064a\u0629 \u064a\u0631\u0647\u0628 \u0628\u0647\u0627 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0641\u064a \u0645\u0643\u0629\u060c \u0641\u062a\u062d\u0631\u0643 \u0628\u062c\u064a\u0634\u0647 \u062d\u062a\u0649 \u0646\u0632\u0644 \u0628\u0647 \u0648\u0627\u062f\u064a \u0639\u064f\u0633\u0641\u0627\u0646 - \u0642\u0631\u064a\u0629 \u0628\u064a\u0646 \u0645\u0643\u0629 \u0648\u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0639\u0644\u0649 \u0646\u062d\u0648 \u064a\u0648\u0645\u064a\u0646 \u0645\u0646 \u0645\u0643\u0629 - \u0648\u0647\u0646\u0627\u0643 \u0627\u0633\u062a\u062f\u0639\u0649 \u0623\u0628\u0627 \u0628\u0643\u0631 \u0627\u0644\u0635\u062f\u064a\u0642\u060c \u0648\u0623\u0639\u0637\u0627\u0647 \u0639\u0634\u0631\u0629 \u0641\u0648\u0627\u0631\u0633 \u0645\u0646 \u0623\u0635\u062d\u0627\u0628\u0647 \u0648\u0623\u0645\u0631\u0647 \u0628\u0623\u0646 \u064a\u062a\u062d\u0631\u0643 \u0628\u0647\u0645 \u0646\u062d\u0648 \u0645\u0643\u0629 \u0644\u064a\u0628\u062b \u0627\u0644\u0630\u0639\u0631 \u0648\u0627\u0644\u0641\u0632\u0639 \u0641\u064a \u0646\u0641\u0648\u0633\u0647\u0645\u060c \u0641\u0627\u062a\u062c\u0647 \u0627\u0644\u0635\u062f\u064a\u0642 \u0628\u0627\u0644\u0641\u0631\u0633\u0627\u0646 \u0627\u0644\u0639\u0634\u0631\u0629 \u0646\u062d\u0648 \u0645\u0643\u0629 \u062d\u062a\u0649 \u0648\u0635\u0644 \u0628\u0647\u0645 \u0643\u064f\u0631\u0627\u0639 \u0627\u0644\u063a\u0645\u064a\u0645 \u060c \u0648\u0647\u0648 \u0645\u0643\u0627\u0646 \u0642\u0631\u064a\u0628 \u062c\u062f\u0627\u064b \u0645\u0646 \u0645\u0643\u0629\u060c \u0641\u0633\u0645\u0639\u062a \u0642\u0631\u064a\u0634 \u0628\u0630\u0644\u0643 \u0641\u0638\u0646\u062a \u0623\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa \u064a\u0646\u0648\u064a \u063a\u0632\u0648\u0647\u0627 \u0641\u0627\u0646\u062a\u0627\u0628\u0647\u0627 \u0627\u0644\u062e\u0648\u0641 \u0648\u0627\u0644\u0641\u0632\u0639 \u0648\u0627\u0644\u0631\u0639\u0628\u060c \u0648\u0633\u0627\u062f \u0635\u0641\u0648\u0641\u0647\u0627 \u0627\u0644\u0630\u0639\u0631\u060c \u0647\u0630\u0627 \u0647\u0648 \u0627\u0644\u0630\u064a \u0647\u062f\u0641 \u0625\u0644\u064a\u0647 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0628\u0647\u0630\u0647 \u0627\u0644\u062d\u0631\u0643\u0629 \u0627\u0644\u062a\u064a \u0643\u0644\u0641 \u0627\u0644\u0635\u062f\u064a\u0642 \u0623\u0646 \u064a\u0642\u0648\u0645 \u0628\u0647\u0627 \u060c \u0623\u0645\u0627 \u0627\u0644\u0635\u062f\u064a\u0642 \u0648\u0641\u0631\u0633\u0627\u0646\u0647 \u0627\u0644\u0639\u0634\u0631\u0629 \u0641\u0628\u0639\u062f \u0623\u0646 \u0648\u0635\u0644\u0648\u0627 \u0643\u064f\u0631\u0627\u0639 \u0627\u0644\u063a\u0645\u064a\u0645 - \u0645\u0648\u0636\u0639 \u0628\u0646\u0627\u062d\u064a\u0629 \u0627\u0644\u062d\u062c\u0627\u0632 \u0628\u064a\u0646 \u0645\u0643\u0629 \u0648\u0627\u0644\u0645\u062f\u064a\u0646\u0629 - \u0648\u0639\u0644\u0645\u0648\u0627 \u0623\u0646\u0647\u0645 \u0642\u062f \u0623\u062d\u062f\u062b\u0648\u0627 \u0627\u0644\u0630\u0639\u0631 \u0648\u0627\u0644\u0641\u0632\u0639 \u0641\u064a \u0646\u0641\u0648\u0633 \u0623\u0647\u0644 \u0645\u0643\u0629 \u0639\u0627\u062f\u0648\u0627 \u0633\u0627\u0644\u0645\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0641\u062a\u062d\u0631\u0643 \u0628\u062c\u064a\u0634\u0647 \u0639\u0627\u0626\u062f\u0627\u064b \u0625\u0644\u0649 \u0627\u0644\u0645\u062f\u064a\u0646\u0629.",null)
B.aHi=new A.a("\u0648\u0639\u0646\u062f\u0645\u0627 \u0648\u0635\u0644 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0625\u0644\u0649 \u0628\u0637\u0646 \u063a\u0631\u0627\u0646 - \u0648\u0627\u062f \u0628\u064a\u0646 \u0633\u0627\u064a\u0629 \u0648\u0645\u0643\u0629 - \u062d\u064a\u062b \u0644\u0642\u064a \u0627\u0644\u0634\u0647\u062f\u0627\u0621 \u0645\u0646 \u0623\u0635\u062d\u0627\u0628\u0647 \u0645\u0635\u0631\u0639\u0647\u0645 \u0639\u0644\u0649 \u0623\u064a\u062f\u064a \u0627\u0644\u062e\u0648\u0646\u0629 \u0645\u0646 \u0647\u0630\u064a\u0644\u060c \u062a\u0631\u0651\u062d\u0645 \u0639\u0644\u0649 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0634\u0647\u062f\u0627\u0621 \u0648\u062f\u0639\u0627 \u0644\u0647\u0645.",null)
