B.aIJ=new A.a("\u0642\u062f\u0645 \u062c\u0639\u0641\u0631 \u0628\u0646 \u0623\u0628\u064a \u0637\u0627\u0644\u0628 \u0648\u0635\u062d\u0628\u0647 \u0645\u0646 \u0645\u0647\u0627\u062c\u0631\u064a \u0627\u0644\u062d\u0628\u0634\u0629 \u0639\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u064a\u0648\u0645 \u0641\u062a\u062d \u062e\u064a\u0628\u0631\u060c \u0641\u0642\u0628\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0628\u064a\u0646 \u0639\u064a\u0646\u064a\u0647 \u0648\u0627\u0644\u062a\u0632\u0645\u0647 \u0648\u0642\u0627\u0644: \u0645\u0627 \u0623\u062f\u0631\u064a \u0628\u0623\u064a\u0647\u0645\u0627 \u0623\u0646\u0627 \u0623\u0633\u0631 \u0628\u0641\u062a\u062d \u062e\u064a\u0628\u0631 \u0623\u0645 \u0628\u0642\u062f\u0648\u0645 \u062c\u0639\u0641\u0631\u060c \u0648\u0643\u0627\u0646 \ufdfa \u0642\u062f \u0627\u0631\u0633\u0644 \u0641\u064a \u0637\u0644\u0628\u0647\u0645 \u0645\u0646 \u0627\u0644\u0646\u062c\u0627\u0634\u064a\u060c \u0639\u0645\u0631\u0648 \u0628\u0646 \u0623\u0645\u064a\u0629 \u0627\u0644\u0636\u0645\u0631\u064a \u0641\u062d\u0645\u0644\u0647\u0645 \u0641\u064a \u0633\u0641\u064a\u0646\u062a\u064a\u0646 \u0648\u0648\u0627\u0641\u0642 \u0642\u062f\u0648\u0645\u0647\u0645 \u0639\u0644\u064a\u0647 \u064a\u0648\u0645 \u0641\u062a\u062d \u062e\u064a\u0628\u0631\u060c \u0648\u0642\u062f \u0631\u0627\u0641\u0642 \u062c\u0639\u0641\u0631 \u0641\u064a \u0642\u062f\u0648\u0645\u0647 \u0623\u0628\u0648 \u0645\u0648\u0633\u0649 \u0627\u0644\u0627\u0634\u0639\u0631\u064a \u0648\u0645\u0646 \u0643\u0627\u0646 \u0628\u0635\u062d\u0628\u062a\u0647 \u0645\u0646 \u0627\u0644\u0623\u0634\u0639\u0631\u064a\u064a\u0646\u060c \u0641\u0639\u0646 \u0623\u0628\u064a \u0645\u0648\u0633\u0649 \u0627\u0644\u0627\u0634\u0639\u0631\u064a \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0642\u0627\u0644: \u0628\u0644\u063a\u0646\u0627 \u0645\u062e\u0631\u062c \u0627\u0644\u0646\u0628\u064a \ufdfa \u0648\u0646\u062d\u0646 \u0628\u0627\u0644\u064a\u0645\u0646\u060c \u0641\u062e\u0631\u062c\u0646\u0627 \u0645\u0647\u0627\u062c\u0631\u064a\u0646 \u0625\u0644\u064a\u0647 \u0623\u0646\u0627 \u0648\u0623\u062e\u0648\u0627\u0646 \u0644\u064a \u0623\u0646\u0627 \u0623\u0635\u063a\u0631\u0647\u0645 \u0623\u062d\u062f\u0647\u0645 \u0623\u0628\u0648 \u0628\u0631\u062f\u0629 \u0648\u0627\u0644\u0622\u062e\u0631 \u0623\u0628\u0648 \u0631\u0647\u0645 \u0625\u0645\u0627 \u0642\u0627\u0644: \u0641\u064a \u0628\u0636\u0639 \u0648\u0625\u0645\u0627 \u0642\u0627\u0644 \u0641\u064a \u062b\u0644\u0627\u062b\u0629 \u0648\u062e\u0645\u0633\u064a\u0646 \u0623\u0648 \u0627\u062b\u0646\u064a\u0646 \u0648\u062e\u0645\u0633\u064a\u0646 \u0631\u062c\u0644\u0627\u064b \u0645\u0646 \u0642\u0648\u0645\u064a\u060c \u0641\u0631\u0643\u0628\u0646\u0627 \u0627\u0644\u0633\u0641\u064a\u0646\u0629 \u0641\u0623\u0644\u0642\u062a\u0646\u0627 \u0633\u0641\u064a\u0646\u062a\u0646\u0627 \u0627\u0644\u0649 \u0627\u0644\u0646\u062c\u0627\u0634\u064a \u0628\u0627\u0644\u062d\u0628\u0634\u0629 \u0641\u0648\u0627\u0641\u0642\u0646\u0627 \u062c\u0639\u0641\u0631 \u0628\u0646 \u0627\u0628\u064a \u0637\u0627\u0644\u0628 \u0641\u0623\u0642\u0645\u0646\u0627 \u062c\u0645\u064a\u0639\u0627\u064b\u060c \u0641\u0648\u0627\u0641\u0642\u0646\u0627 \u0627\u0644\u0646\u0628\u064a \ufdfa \u062d\u064a\u0646 \u0627\u0641\u062a\u062a\u062d \u062e\u064a\u0628\u0631.",null)
B.b3p=new A.a("\u0644\u0642\u062f \u0645\u0643\u062b \u062c\u0639\u0641\u0631 \u0648\u0625\u062e\u0648\u0627\u0646\u0647 \u0641\u064a \u0627\u0644\u062d\u0628\u0634\u0629 \u0628\u0636\u0639\u0629 \u0639\u0634\u0631 \u0639\u0627\u0645\u0627\u064b\u060c \u0646\u0632\u0644 \u062e\u0644\u0627\u0644\u0647\u0627 \u0642\u0631\u0622\u0646 \u0643\u062b\u064a\u0631 \u0648\u062f\u0627\u0631\u062a \u0645\u0639\u0627\u0631\u0643 \u0634\u062a\u0649 \u0645\u0639 \u0627\u0644\u0643\u0641\u0627\u0631 \u0648\u062a\u0642\u0644\u0628 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646 \u0642\u0628\u0644 \u0627\u0644\u0647\u062c\u0631\u0629 \u0627\u0644\u0639\u0627\u0645\u0629 \u0648\u0628\u0639\u062f\u0647\u0627 \u0641\u064a \u0623\u0637\u0648\u0627\u0631 \u0645\u062a\u0628\u0627\u064a\u0646\u0629\u060c \u062d\u062a\u0649 \u0638\u0646 \u0627\u0644\u0628\u0639\u0636 \u0623\u0646 \u0645\u0647\u0627\u062c\u0631\u064a \u0627\u0644\u062d\u0628\u0634\u0629 - \u0648\u0642\u062f \u0641\u0627\u062a\u0647\u0645 \u0647\u0630\u0627 \u0643\u0644\u0647 - \u0623\u0642\u0644 \u0642\u062f\u0631\u0627\u064b \u0645\u0646 \u063a\u064a\u0631\u0647\u0645.",null)
