B.ba2=new A.a("\u0643\u0627\u0646 \u0645\u0648\u0642\u0641 \u062e\u062f\u064a\u062c\u0629 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0627 \u0645\u0646 \u062e\u0628\u0631 \u0627\u0644\u0648\u062d\u064a \u064a\u062f\u0644 \u0639\u0644\u0649 \u0633\u0639\u0629 \u0625\u062f\u0631\u0627\u0643\u0647\u0627\u060c \u062d\u064a\u062b \u0642\u0627\u0631\u0646\u062a \u0628\u064a\u0646 \u0645\u0627 \u0633\u0645\u0639\u062a \u0648\u0648\u0627\u0642\u0639 \u0627\u0644\u0646\u0628\u064a \ufdfa \u060c \u0648\u0643\u0627\u0646\u062a \u0645\u0648\u0642\u0646\u0629 \u0628\u0623\u0646 \u0632\u0648\u062c\u0647\u0627 \u0641\u064a\u0647 \u0645\u0646 \u0645\u062d\u0627\u0633\u0646 \u0627\u0644\u0623\u062e\u0644\u0627\u0642 \u0627\u0644\u0631\u0635\u064a\u0646\u0629\u060c \u0648\u0641\u0636\u0627\u0626\u0644 \u0627\u0644\u0634\u064a\u0645 \u0627\u0644\u0645\u0631\u0636\u064a\u0629\u060c \u0645\u0627 \u064a\u0636\u0645\u0646 \u0644\u0647 \u0627\u0644\u0641\u0648\u0632 \u0648\u064a\u062d\u0642\u0642 \u0644\u0647 \u0627\u0644\u0646\u062c\u0627\u062d \u0648\u0627\u0644\u0641\u0644\u0627\u062d.",null)
B.bcs=new A.a("\u0625\u0646 \u0627\u0644\u0633\u064a\u062f\u0629 \u062e\u062f\u064a\u062c\u0629 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0627 \u0645\u062b\u0627\u0644 \u062d\u0633\u0646 \u0648\u0642\u062f\u0648\u0629 \u0631\u0641\u064a\u0639\u0629 \u0644\u0632\u0648\u062c\u0627\u062a \u0627\u0644\u062f\u0639\u0627\u0629\u060c \u0641\u0627\u0644\u062f\u0627\u0639\u064a\u0629 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u0644\u064a\u0633 \u0643\u0628\u0627\u0642\u064a \u0627\u0644\u0631\u062c\u0627\u0644 \u0627\u0644\u0630\u064a\u0646 \u0647\u0645 \u0628\u0639\u064a\u062f\u0648\u0646 \u0639\u0646 \u0623\u0639\u0628\u0627\u0621 \u0627\u0644\u062f\u0639\u0648\u0629\u060c \u0648\u0645\u0646 \u0627\u0644\u0635\u0639\u0628 \u0623\u0646 \u064a\u0643\u0648\u0646 \u0645\u062b\u0644\u0647\u0645 \u0641\u064a \u0643\u0644 \u0634\u064a\u0621\u060c \u0625\u0646\u0647 \u0635\u0627\u062d\u0628 \u0647\u0645\u0651\u064d \u0648\u0631\u0633\u0627\u0644\u0629\u060c \u0647\u0645\u0651\u064d \u0639\u0644\u0649 \u0636\u064a\u0627\u0639 \u0623\u0645\u062a\u0647\u060c \u0648\u0627\u0646\u062a\u0634\u0627\u0631 \u0627\u0644\u0641\u0633\u0627\u062f\u060c \u0648\u0632\u064a\u0627\u062f\u0629 \u0634\u0648\u0643\u0629 \u0623\u0647\u0644\u0647\u060c \u0648\u0647\u0645\u0651\u064d \u0644\u0645\u0627 \u064a\u0635\u064a\u0628 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0641\u064a \u0645\u0634\u0627\u0631\u0642 \u0627\u0644\u0623\u0631\u0636 \u0648\u0645\u063a\u0627\u0631\u0628\u0647\u0627 \u0645\u0646 \u0645\u0624\u0627\u0645\u0631\u0627\u062a\u060c \u0648\u0638\u0644\u0645 \u0648\u062c\u0648\u0639\u060c \u0648\u0625\u0630\u0644\u0627\u0644\u060c \u0648\u0645\u0627 \u064a\u0635\u064a\u0628 \u0627\u0644\u062f\u0639\u0627\u0629 \u0645\u0646\u0647\u0645 \u0645\u0646 \u062a\u0634\u0631\u064a\u062f \u0648\u062a\u0636\u064a\u064a\u0642 \u0648\u062a\u0646\u0643\u064a\u0644\u060c \u0648\u0628\u0639\u062f \u0630\u0644\u0643 \u0647\u0648 \u0635\u0627\u062d\u0628 \u0631\u0633\u0627\u0644\u0629 \u0648\u0627\u062c\u0628 \u0639\u0644\u064a\u0647 \u062a\u0628\u0644\u064a\u063a\u0647\u0627 \u0644\u0644\u0622\u062e\u0631\u064a\u0646\u060c \u0648\u0647\u0630\u0627 \u0627\u0644\u0648\u0627\u062c\u0628 \u064a\u062a\u0637\u0644\u0628 \u0648\u0642\u062a\u064b\u0627 \u0637\u0648\u064a\u0644\u0627\u064b \u064a\u0623\u062e\u0630 \u0639\u0644\u064a\u0647 \u0623\u0648\u0642\u0627\u062a \u0646\u0648\u0645\u0647 \u0648\u0631\u0627\u062d\u062a\u0647\u060c \u0648\u0623\u0648\u0642\u0627\u062a \u0632\u0648\u062c\u062a\u0647 \u0648\u0623\u0628\u0646\u0627\u0626\u0647\u060c \u0648\u064a\u062a\u0637\u0644\u0628 \u062a\u0636\u062d\u064a\u0629 \u0628\u0627\u0644\u0645\u0627\u0644 \u0648\u0627\u0644\u0648\u0642\u062a \u0648\u0627\u0644\u062f\u0646\u064a\u0627 \u0628\u0623\u0633\u0631\u0647\u0627 \u0645\u0627 \u062f\u0627\u0645 \u0630\u0644\u0643 \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647 \u0648\u0645\u0631\u0636\u0627\u062a\u0647\u060c \u0648\u0625\u0646 \u0623\u0648\u062a\u064a\u062a \u0627\u0644\u0632\u0648\u062c\u0629 \u0645\u0646 \u0627\u0644\u0623\u062e\u0644\u0627\u0642 \u0648\u0627\u0644\u062a\u0642\u0648\u0649 \u0648\u0627\u0644\u062c\u0645\u0627\u0644 \u0648\u0627\u0644\u062d\u0633\u0628 \u0645\u0627 \u0623\u0648\u062a\u064a\u062a\u060c \u0625\u0646\u0647 \u064a\u062d\u062a\u0627\u062c \u0625\u0644\u0649 \u0632\u0648\u062c\u0629 \u062a\u062f\u0631\u0643 \u0648\u0627\u062c\u0628 \u0627\u0644\u062f\u0639\u0648\u0629 \u0648\u0623\u0647\u0645\u064a\u062a\u0647\u060c \u0648\u062a\u062f\u0631\u0643 \u062a\u0645\u0627\u0645\u064b\u0627 \u0645\u0627 \u064a\u0642\u0648\u0645 \u0628\u0647 \u0627\u0644\u0632\u0648\u062c \u0648\u0645\u0627 \u064a\u062a\u062d\u0645\u0644\u0647 \u0645\u0646 \u0623\u0639\u0628\u0627\u0621\u060c \u0648\u0645\u0627 \u064a\u0639\u0627\u0646\u064a\u0647 \u0645\u0646 \u0645\u0634\u0627\u0642\u0651\u060c \u0641\u062a\u0642\u0641 \u0625\u0644\u0649 \u062c\u0627\u0646\u0628\u0647 \u062a\u064a\u0633\u0631 \u0644\u0647 \u0645\u0647\u0645\u062a\u0647 \u0648\u062a\u0639\u064a\u0646\u0647 \u0639\u0644\u064a\u0647\u0627\u060c \u0644\u0627 \u0623\u0646 \u062a\u0642\u0641 \u0639\u0627\u0626\u0642\u0627 \u0648\u0634\u0648\u0643\u0629 \u0641\u064a \u0637\u0631\u064a\u0642\u0647.",null)
