B.aZ5=new A.a("\u0643\u0627\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0645\u062b\u0627\u0644\u0627\u064b \u0639\u0627\u0644\u064a\u064b\u0627 \u0644\u0644\u0648\u0641\u0627\u0621 \u0648\u0631\u062f \u0627\u0644\u062c\u0645\u064a\u0644 \u0644\u0623\u0647\u0644\u0647\u060c \u0641\u0642\u062f \u0643\u0627\u0646 \u0641\u064a \u063a\u0627\u064a\u0629 \u0627\u0644\u0648\u0641\u0627\u0621 \u0645\u0639 \u0632\u0648\u062c\u062a\u0647 \u0627\u0644\u0645\u062e\u0644\u0635\u0629\u060c \u0641\u064a \u062d\u064a\u0627\u062a\u0647\u0627 \u0648\u0628\u0639\u062f \u0645\u0645\u0627\u062a\u0647\u0627\u060c \u0648\u0642\u062f \u0628\u0634\u0631\u0647\u0627 \ufdfa \u0628\u0628\u064a\u062a \u0641\u064a \u0627\u0644\u062c\u0646\u0629 \u0641\u064a \u062d\u064a\u0627\u062a\u0647\u0627\u060c \u0648\u0623\u0628\u0644\u063a\u0647\u0627 \u0633\u0644\u0627\u0645 \u0627\u0644\u0644\u0647 \u062c\u0644 \u0648\u0639\u0644\u0627\u060c \u0648\u0633\u0644\u0627\u0645 \u062c\u0628\u0631\u064a\u0644 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645\u060c \u0641\u0639\u0646 \u0623\u0628\u064a \u0647\u0631\u064a\u0631\u0629 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0642\u0627\u0644: \u0623\u062a\u0649 \u062c\u0628\u0631\u064a\u0644 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0641\u0642\u0627\u0644: \u064a\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647\u060c \u0647\u0630\u0647 \u062e\u062f\u064a\u062c\u0629 \u0642\u062f \u0623\u062a\u062a\u0643 \u0645\u0639\u0647\u0627 \u0625\u0646\u0627\u0621 \u0641\u064a\u0647 \u0625\u062f\u0627\u0645 -\u0623\u0648 \u0637\u0639\u0627\u0645 \u0623\u0648 \u0634\u0631\u0627\u0628- \u0641\u0625\u0630\u0627 \u0647\u064a \u0623\u062a\u062a\u0643 \u0641\u0627\u0642\u0631\u0623 \u0639\u0644\u064a\u0647\u0627 \u0627\u0644\u0633\u0644\u0627\u0645 \u0645\u0646 \u0631\u0628\u0647\u0627 \u0639\u0632 \u0648\u062c\u0644 \u0648\u0645\u0646\u064a \u0648\u0628\u0634\u0631\u0647\u0627 \u0628\u0628\u064a\u062a \u0641\u064a \u0627\u0644\u062c\u0646\u0629 \u0645\u0646 \u0642\u0635\u0628 -\u0644\u0624\u0644\u0624 \u0645\u062c\u0648\u0641 \u0648\u064a\u0627\u0642\u0648\u062a- \u0644\u0627 \u0635\u062e\u0628 \u0641\u064a\u0647 \u0648\u0644\u0627 \u0646\u0635\u0628.",null)
B.b9o=new A.a("\u0648\u062a\u0630\u0643\u0631 \u0639\u0627\u0626\u0634\u0629 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0627 \u0648\u0641\u0627\u0621 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0644\u062e\u062f\u064a\u062c\u0629 \u0628\u0639\u062f \u0648\u0641\u0627\u062a\u0647\u0627 \u0628\u0642\u0648\u0644\u0647\u0627: \u0645\u0627 \u063a\u0631\u062a \u0639\u0644\u0649 \u0623\u062d\u062f \u0645\u0646 \u0646\u0633\u0627\u0621 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0645\u0627 \u063a\u0631\u062a \u0639\u0644\u0649 \u062e\u062f\u064a\u062c\u0629\u060c \u0648\u0645\u0627 \u0631\u0623\u064a\u062a\u0647\u0627\u060c \u0648\u0644\u0643\u0646 \u0643\u0627\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa \u064a\u0643\u062b\u0631 \u0630\u0643\u0631\u0647\u0627\u060c \u0648\u0631\u0628\u0645\u0627 \u0630\u0628\u062d \u0627\u0644\u0634\u0627\u0629 \u062b\u0645 \u064a\u0642\u0637\u0651\u0639\u0647\u0627 \u0623\u0639\u0636\u0627\u0621\u064b \u062b\u0645 \u064a\u0628\u0639\u062b\u0647\u0627 \u0641\u064a \u0635\u062f\u0627\u0626\u0642 \u062e\u062f\u064a\u062c\u0629\u060c \u0641\u0631\u0628\u0645\u0627 \u0642\u0644\u062a \u0644\u0647: \u0643\u0623\u0646\u0647 \u0644\u0645 \u064a\u0643\u0646 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0627\u0645\u0631\u0623\u0629 \u0625\u0644\u0627 \u062e\u062f\u064a\u062c\u0629\u061f \u0641\u064a\u0642\u0648\u0644: \u0625\u0646\u0647\u0627 \u0643\u0627\u0646\u062a \u0648\u0643\u0627\u0646\u062a \u0648\u0643\u0627\u0646 \u0644\u064a \u0645\u0646\u0647\u0627 \u0627\u0644\u0648\u0644\u062f.",null)
B.aI_=new A.a("\u0648\u0623\u0638\u0647\u0631 \ufdfa \u0627\u0644\u0628\u0634\u0627\u0634\u0629 \u0648\u0627\u0644\u0633\u0631\u0648\u0631 \u0644\u0623\u062e\u062a \u062e\u062f\u064a\u062c\u0629 \u0644\u0645\u0627 \u0627\u0633\u062a\u0623\u0630\u0646\u062a \u0639\u0644\u064a\u0647 \u0644\u062a\u0630\u0643\u0651\u064f\u0631\u0647 \u062e\u062f\u064a\u062c\u0629\u060c \u0641\u0639\u0646 \u0639\u0627\u0626\u0634\u0629 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0627 \u0642\u0627\u0644\u062a: \u0627\u0633\u062a\u0623\u0630\u0646\u062a \u0647\u0627\u0644\u0629 \u0628\u0646\u062a \u062e\u0648\u064a\u0644\u062f \u0623\u062e\u062a \u062e\u062f\u064a\u062c\u0629 \u0639\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u0639\u0631\u0641 \u0627\u0633\u062a\u0626\u0630\u0627\u0646 \u062e\u062f\u064a\u062c\u0629 -\u0644\u062a\u0634\u0627\u0628\u0647 \u0635\u0648\u062a\u064a\u0647\u0645\u0627-  \u0641\u0627\u0631\u062a\u0627\u062d \u0644\u0630\u0644\u0643\u060c \u0641\u0642\u0627\u0644: \u0627\u0644\u0644\u0647\u0645 \u0647\u0627\u0644\u0629 \u0628\u0646\u062a \u062e\u0648\u064a\u0644\u062f\u060c \u0641\u063a\u0631\u062a \u0641\u0642\u0644\u062a: \u0648\u0645\u0627 \u062a\u0630\u0643\u0631 \u0645\u0646 \u0639\u062c\u0648\u0632 \u0645\u0646 \u0639\u062c\u0627\u0626\u0632 \u0642\u0631\u064a\u0634 \u062d\u0645\u0631\u0627\u0621 \u0627\u0644\u0634\u062f\u0642\u064a\u0646 -\u064a\u0639\u0646\u064a \u0644\u0627 \u0623\u0633\u0646\u0627\u0646 \u0644\u0647\u0627 \u0645\u0646 \u0627\u0644\u0643\u0628\u0631-  \u0647\u0644\u0643\u062a \u0641\u064a \u0627\u0644\u062f\u0647\u0631 \u0641\u0623\u0628\u062f\u0644\u0643 \u0627\u0644\u0644\u0647 \u062e\u064a\u0631\u064b\u0627 \u0645\u0646\u0647\u0627\u060c \u0648\u0623\u0638\u0647\u0631 \ufdfa \u0627\u0644\u062d\u0641\u0627\u0648\u0629 \u0628\u0627\u0645\u0631\u0623\u0629 \u0643\u0627\u0646\u062a \u062a\u0623\u062a\u064a\u0647\u0645 \u0632\u0645\u0646 \u062e\u062f\u064a\u062c\u0629 \u0648\u0628\u064a\u0646 \u0623\u0646 \u062d\u0641\u0638 \u0627\u0644\u0639\u0647\u062f \u0645\u0646 \u0627\u0644\u0625\u064a\u0645\u0627\u0646.",null)
